#!/usr/bin/env sh
# Statusline renderer for Claude Code — SUPERSET of ~/.claude/joyia-statusline.sh.
#
# WHY A SEPARATE FILE: joyia-statusline.sh is INSTALLED/REGENERATED by
# `joyia agent --setup`, so edits there are not durable. This file reproduces
# every field that renderer showed (JoyIA mark, model, ctx %, cost, git branch,
# worktree, +adds/-dels) and adds the fields the vendored one lacked. The
# vendored script is left untouched on disk as a fallback/reference.
#
# Called by scripts/cost-ledger-capture.sh with the statusLine JSON on stdin.
#
# Line 1 (one concise line, fixed-width-ish scalars only):
#   JoyIA · <model> <effort> · ctx <tokens> <pct>% · 5h <pct>% · 7d <pct>%
# Line 2 (the SPEND line: both dollar figures together, today first since that is the one
# measured against the cap. Its own line since 0.5.1 -- sharing line 1 overflowed one
# terminal width and wrapped):
#   session $<cost> · today: $<spent>/$<cap> gw
# Line 3 (variable-length names, which can be long, + the previous git fields):
#   <dir basename> · <branch> · <worktree> · +<added>/-<removed>
#
# The model's context-window suffix is abbreviated for width: "Opus 5 (1M context)"
# renders as "Opus 5 (1M)".
#
# DELIBERATELY OMITTED (2026-08-26, user call): the context WINDOW SIZE (already
# implied by the model name, e.g. "Opus 5 (1M)") and the per-request token
# breakdown (fresh / cache-read / cache-write) -- ctx alone is the signal wanted,
# the rest was noise. The jq pass no longer extracts them at all.
#
# Every field is optional: anything missing or null is dropped, not printed as
# "null" or "0". No network calls; one jq pass; git is best-effort and local.

# Argument handling comes BEFORE the stdin read. This script's normal input is the
# statusLine JSON on stdin, so a user probing it with --help would otherwise block on an
# empty terminal or render a line and have that read as help output.
case "${1:-}" in
  -h|--help)
    cat <<'USAGE'
statusline-render.sh — render the Claude Code status line.

Reads the statusLine JSON payload on stdin and prints up to three lines:

  CLOUD SESSION:
    JoyIA · <model> <effort> · ctx <tokens> <pct>% · 5h <pct>% · 7d <pct>%
    session $<cost> · today: $<billed>/$<cap> gw · local saved $<saved>
  LOCAL SESSION (ANTHROPIC_BASE_URL=localhost:8000-8010):
    <model> <effort> · ctx <tokens> <pct>% · 5h <pct>% · 7d <pct>%
    local session saved $<session_phantom> · today: $<daily_saved> saved with free agents
    (no JoyIA mark, no cloud spend, no cap)
  FREE_API SESSION (ANTHROPIC_BASE_URL=localhost:4141):
    <model> <effort> · ctx <tokens> <pct>% · 5h <pct>% · 7d <pct>%
    free api session saved $<session_phantom> · today: $<daily_saved> saved with free agents
    (no JoyIA mark, no cloud spend, no cap)

  <dir basename> · <branch> · <worktree> · +<added>/-<removed>

Usage:
  <statusline JSON> | statusline-render.sh
  statusline-render.sh --help

The budget line comes from the sibling `cost-tracker` CLI. On CLOUD sessions it is on the
GATEWAY axis (markup applied, figures match the cap the gateway's refusal quotes).
On LOCAL and FREE_API sessions the cloud figure and cap are SUPPRESSED entirely; instead it
shows "local session saved $X · today: $Y saved with free agents" (LOCAL) or
"free api session saved $X · today: $Y saved with free agents" (FREE_API) where X is this
session's phantom (what local/free work would have cost at Opus rates) and Y is the combined
daily savings across all local sessions + free API sessions + dispatch savings from the
savings-ledger. Detection is via ANTHROPIC_BASE_URL (ports 8000-8010 = LOCAL, 4141 = FREE_API),
never CLAUDE_IS_LOCAL (which leaks into later cloud sessions).

Every field is optional — anything missing or null is dropped rather than printed as
"null" or "0". No network calls; git is best-effort and local. Always exits 0 so a
rendering problem can never break the status line.

Environment:
  COST_TRACKER_STATUSLINE=0   omit the budget line entirely
  COST_TRACKER_LEDGER_DIR     per-session ledger dir (default ~/.claude/cost-ledger); the
                              free-lane phantom is read from this session's entry there
USAGE
    exit 0
    ;;
  -?*)
    printf 'statusline-render.sh: unrecognised option: %s\n' "$1" >&2
    printf "Try 'statusline-render.sh --help'.\n" >&2
    exit 2
    ;;
esac

LC_ALL=C
export LC_ALL

INPUT="$(cat)"

# --- extract: ONE jq pass, US-delimited, empty string for missing/null --------
# Delimiter is \037 (ASCII US), NOT tab: tab is an IFS *whitespace* character, so
# `read` collapses runs of tabs and every field after an absent one shifts left
# (observed: a missing .effort.level silently pushed the directory into EFFORT).
# \037 is non-whitespace, so empty fields are preserved exactly.
# Field order must match the `read` below.
FIELDS=""
if command -v jq >/dev/null 2>&1; then
  FIELDS=$(printf '%s' "$INPUT" | jq -r '
    def s: if . == null then "" else (.|tostring) end;
    def pct: if . == null then "" else (.|round|tostring) end;
    [ (.model.display_name          // "Claude")
    , (.effort.level                // null      | s)
    , (.workspace.current_dir       // .cwd // "" )
    , (.context_window.total_input_tokens   // null | s)
    , (.context_window.used_percentage      // null | pct)
    , (.cost.total_cost_usd         // null      | s)
    , (.cost.total_lines_added      // 0         | s)
    , (.cost.total_lines_removed    // 0         | s)
    , (.rate_limits.five_hour.used_percentage // null | pct)
    , (.rate_limits.seven_day.used_percentage // null | pct)
    , (.session_id                  // ""       | s)
    ] | join("")
  ' 2>/dev/null || true)
fi

MODEL=Claude; EFFORT=; CWD=; CTX_CUR=; CTX_PCT=
COST=; ADD=0; DEL=0; FIVEH=; SEVEND=; SID=
if [ -n "$FIELDS" ]; then
  # shellcheck disable=SC2162
  IFS="$(printf '\037')" read MODEL EFFORT CWD CTX_CUR CTX_PCT \
                COST ADD DEL FIVEH SEVEND SID <<EOF
$FIELDS
EOF
fi
[ -n "$MODEL" ] || MODEL=Claude
[ -n "$CWD" ] || CWD="$PWD"
case "$ADD" in ''|*[!0-9]*) ADD=0 ;; esac
case "$DEL" in ''|*[!0-9]*) DEL=0 ;; esac
DIRBASE=$(basename "$CWD" 2>/dev/null || printf '%s' "$CWD")

# LEDGER_DIR for per-session phantom lookup (defaults to ~/.claude/cost-ledger)
LEDGER_DIR="${COST_TRACKER_LEDGER_DIR:-$HOME/.claude/cost-ledger}"

# Abbreviate the model's context-window suffix: "Opus 5 (1M context)" -> "Opus 5 (1M)".
# The word "context" is pure padding here — nothing else on the line could be measured in
# M, and the whole segment exists to say which window this session has. Cheap 8 columns on
# the line that has the least room to spare. Substitution only, so a display name without
# the suffix is passed through untouched.
MODEL=$(printf '%s' "$MODEL" | sed 's/ context)/)/')

# Cost -> 2dp. C locale forced above so "1.2345" parses under de_DE.
COST_FMT=
if [ -n "$COST" ]; then
  COST_FMT=$(printf '%.2f' "$COST" 2>/dev/null || printf '%s' "$COST")
fi

# --- git (best-effort, local only) -------------------------------------------
BRANCH=; WORKTREE=
if command -v git >/dev/null 2>&1; then
  BRANCH=$(git -C "$CWD" branch --show-current 2>/dev/null || true)
  TOPLEVEL=$(git -C "$CWD" rev-parse --show-toplevel 2>/dev/null || true)
  [ -n "$TOPLEVEL" ] && WORKTREE=$(basename "$TOPLEVEL")
fi

# --- resolve session identity via la-session-identity.sh --------------------
# This replaces the old endpoint-only detection with the canonical resolver.
# The resolver emits JSON with schema_version=1; we parse it with jq.
IDENTITY_JSON=
if command -v la-session-identity.sh >/dev/null 2>&1; then
    IDENTITY_JSON=$(la-session-identity.sh 2>/dev/null) || IDENTITY_JSON=
fi

# Parse resolver output (fallback to legacy detection if resolver unavailable or returns unknown session_kind)
USE_LEGACY_FALLBACK=0
if [ -n "$IDENTITY_JSON" ] && command -v jq >/dev/null 2>&1; then
    SESSION_KIND=$(printf '%s' "$IDENTITY_JSON" | jq -r '.session_kind // "unknown"')
    UNKNOWN_FALLBACK=$(printf '%s' "$IDENTITY_JSON" | jq -r '.unknown_fallback // false')
    # Only use legacy fallback if resolver returns "unknown" session_kind.
    # If resolver returns a valid kind (local/free_api/cloud) but unknown_fallback=true,
    # we trust the session_kind but may fall back to payload for model name.
    if [ "$SESSION_KIND" = "unknown" ]; then
        USE_LEGACY_FALLBACK=1
    fi
fi

if [ "$USE_LEGACY_FALLBACK" = "1" ]; then
    # Legacy fallback: derive from ANTHROPIC_BASE_URL (matches old logic)
    SESSION_KIND="unknown"
    SESSION_EMOJI="❓"
    PROVIDER_DISPLAY="Unknown"
    THEME_IDENTIFIER="unknown"
    SPINNER_PROFILE="unknown"
    case "${ANTHROPIC_BASE_URL:-}" in
        http://localhost:800[0-9]|http://localhost:8010|http://127.0.0.1:800[0-9]|http://127.0.0.1:8010)
            SESSION_KIND="local"
            SESSION_EMOJI="🦾"
            PROVIDER_DISPLAY="Local (unknown backend)"
            THEME_IDENTIFIER="local-sky"
            SPINNER_PROFILE="local-unknown"
            ;;
        http://localhost:4141|http://127.0.0.1:4141)
            SESSION_KIND="free_api"
            SESSION_EMOJI="🌐"
            PROVIDER_DISPLAY="Free API (NVIDIA Nemotron)"
            THEME_IDENTIFIER="free-lime"
            SPINNER_PROFILE="free-api"
            ;;
        https://api.anthropic.com*|*anthropic.com*|*llmgw*)
            SESSION_KIND="cloud"
            SESSION_EMOJI="☁️"
            PROVIDER_DISPLAY="Anthropic (cloud)"
            THEME_IDENTIFIER="cloud-default"
            SPINNER_PROFILE="cloud"
            ;;
    esac
    # Preserve MODEL from input for backward compat
    ACTUAL_MODEL_ID="${MODEL:-unknown}"
    ACTUAL_MODEL_DISPLAY="${MODEL:-unknown}"
    BACKEND_DISPLAY="unknown"
    ROLE_PROFILE="untagged"
    EFFORT="${EFFORT:-medium}"
    THINKING_MODE="unknown"
    EVIDENCE="legacy-fallback"
    UNKNOWN_FALLBACK=true
else
    # Use resolver output
    SESSION_EMOJI=$(printf '%s' "$IDENTITY_JSON" | jq -r '.session_emoji // "❓"')
    ACTUAL_MODEL_ID=$(printf '%s' "$IDENTITY_JSON" | jq -r '.actual_model_id // "unknown"')
    ACTUAL_MODEL_DISPLAY=$(printf '%s' "$IDENTITY_JSON" | jq -r '.actual_model_display // "unknown"')
    PROVIDER_DISPLAY=$(printf '%s' "$IDENTITY_JSON" | jq -r '.provider_display // "Unknown"')
    BACKEND_DISPLAY=$(printf '%s' "$IDENTITY_JSON" | jq -r '.backend_display // "unknown"')
    ROLE_PROFILE=$(printf '%s' "$IDENTITY_JSON" | jq -r '.role_profile // "untagged"')
    # For cloud sessions, keep payload's effort level; for local/free_api, use resolver's
    if [ "$SESSION_KIND" = "cloud" ]; then
        EFFORT="${EFFORT:-medium}"
    else
        EFFORT=$(printf '%s' "$IDENTITY_JSON" | jq -r '.effort // "medium"')
    fi
    THINKING_MODE=$(printf '%s' "$IDENTITY_JSON" | jq -r '.thinking_mode // "unknown"')
    THEME_IDENTIFIER=$(printf '%s' "$IDENTITY_JSON" | jq -r '.theme_identifier // "unknown"')
    SPINNER_PROFILE=$(printf '%s' "$IDENTITY_JSON" | jq -r '.spinner_profile_id // "unknown"')
    EVIDENCE=$(printf '%s' "$IDENTITY_JSON" | jq -r '.evidence // "fallback"')
    UNKNOWN_FALLBACK=$(printf '%s' "$IDENTITY_JSON" | jq -r '.unknown_fallback // false')
fi

# If resolver gave us a valid session_kind but unknown actual_model_id, fall back to payload MODEL
if [ "$ACTUAL_MODEL_ID" = "unknown" ] && [ -n "$MODEL" ]; then
    ACTUAL_MODEL_ID="$MODEL"
    ACTUAL_MODEL_DISPLAY="$MODEL"
fi

# --- collect free-agents telemetry (RAM, token rate) ---------------------------
# Only for local and free_api sessions; cloud sessions don't have local telemetry.
TELEMETRY_RAM=
TELEMETRY_TOK_RATE=
if [ "$SESSION_KIND" = "local" ] || [ "$SESSION_KIND" = "free_api" ]; then
    # RAM segment (la-statusline-segment.sh prints JSON: {"label":"ram","text":"...","level":"..."})
    if command -v la-statusline-segment.sh >/dev/null 2>&1; then
        TELEMETRY_RAM=$(la-statusline-segment.sh 2>/dev/null) || TELEMETRY_RAM=
    fi
    # Token rate segment (la-telemetry-token-rate.sh prints JSON: {"text":"...","rate":...,"fresh":...,"age_s":...,"level":"..."})
    if command -v la-telemetry-token-rate.sh >/dev/null 2>&1; then
        TELEMETRY_TOK_RATE=$(la-telemetry-token-rate.sh 2>/dev/null) || TELEMETRY_TOK_RATE=
    fi
fi

# --- render -------------------------------------------------------------------
DIM=$(printf '\033[2m');    BOLD=$(printf '\033[1m')
RESET=$(printf '\033[0m');  CYAN=$(printf '\033[36m')
YELLOW=$(printf '\033[33m');GREEN=$(printf '\033[32m')
RED=$(printf '\033[31m');   MAGENTA=$(printf '\033[35m')
BLUE=$(printf '\033[34m')
SEP="${DIM} · ${RESET}"

# Line 1: model identity (uses resolver's actual_model_id for truthful display)
MODEL_LABEL="${ACTUAL_MODEL_ID}"
if [ "$SESSION_KIND" = "cloud" ]; then
    LINE1="${BOLD}${BLUE}JoyIA${RESET}${SEP}${BOLD}${MODEL_LABEL}${RESET}"
else
    LINE1="${BOLD}${MODEL_LABEL}${RESET}"
fi
[ -n "$EFFORT" ] && [ "$EFFORT" != "medium" ] && LINE1="${LINE1} ${DIM}${EFFORT}${RESET}"

# ctx: absolute input tokens + percentage. The window SIZE is intentionally not
# shown -- the model name already carries it. Each half is independent so a
# payload with only one of them still renders something useful.
CTXSTR=
if [ -n "$CTX_CUR" ]; then
  CTXSTR="ctx ${CTX_CUR}"
fi
if [ -n "$CTX_PCT" ]; then
  if [ -n "$CTXSTR" ]; then CTXSTR="${CTXSTR} ${CTX_PCT}%"; else CTXSTR="ctx ${CTX_PCT}%"; fi
fi
[ -n "$CTXSTR" ] && LINE1="${LINE1}${SEP}${CYAN}${CTXSTR}${RESET}"

# --- free-agents telemetry on line 1 -------------------------------------------
# Add RAM and token rate for local/free_api sessions
if [ "$SESSION_KIND" = "local" ] || [ "$SESSION_KIND" = "free_api" ]; then
    # RAM telemetry
    if [ -n "$TELEMETRY_RAM" ] && command -v jq >/dev/null 2>&1; then
        RAM_TEXT=$(printf '%s' "$TELEMETRY_RAM" | jq -r '.text // ""' 2>/dev/null)
        RAM_LEVEL=$(printf '%s' "$TELEMETRY_RAM" | jq -r '.level // "ok"' 2>/dev/null)
        if [ -n "$RAM_TEXT" ]; then
            case "$RAM_LEVEL" in
                crit) RAM_COLOR="$RED" ;;
                warn) RAM_COLOR="$YELLOW" ;;
                *) RAM_COLOR="$GREEN" ;;
            esac
            LINE1="${LINE1}${SEP}${RAM_COLOR}${RAM_TEXT}${RESET}"
        fi
    fi
    # Token rate telemetry
    if [ -n "$TELEMETRY_TOK_RATE" ] && command -v jq >/dev/null 2>&1; then
        TOK_TEXT=$(printf '%s' "$TELEMETRY_TOK_RATE" | jq -r '.text // ""' 2>/dev/null)
        TOK_LEVEL=$(printf '%s' "$TELEMETRY_TOK_RATE" | jq -r '.level // "unknown"' 2>/dev/null)
        if [ -n "$TOK_TEXT" ]; then
            case "$TOK_LEVEL" in
                stale) TOK_COLOR="$YELLOW" ;;
                unknown) TOK_COLOR="$DIM" ;;
                *) TOK_COLOR="$CYAN" ;;
            esac
            LINE1="${LINE1}${SEP}${TOK_COLOR}${TOK_TEXT}${RESET}"
        fi
    fi
fi

# --- the TODAY segment (cost-tracker) ----------------------------------------
# Two dollar figures on one line MUST each name their axis, or this reproduces the
# mislabel bug the plugin exists to prevent: the renderer's own figure is the
# SESSION LIFETIME, while the segment below is TODAY ACROSS ALL SESSIONS. So the
# lifetime figure is prefixed "session" only when the today segment is actually
# present — when it is alone there is nothing to confuse it with, and the label
# would just be noise.
#
# Opt out with COST_TRACKER_STATUSLINE=0. --fast keeps this off the history log and
# reads savings from the derived rollup, so it adds ~50ms rather than ~190ms. Wrapped
# so that a failure loses the segment and nothing else: this file must always exit 0.
TODAY_SEG=
DAILY_SAVED=
if [ "${COST_TRACKER_STATUSLINE:-1}" != "0" ]; then
    # RESOLVE $0 THROUGH SYMLINKS FIRST. In the wired setup this file is reached as
    # ~/.claude/scripts/statusline-render.sh, a symlink into the plugin — so a plain
    # dirname "$0" looks for the CLI in ~/.claude/scripts, where it is not, and the
    # segment silently never appeared. Found end-to-end, not by the unit tests, which
    # invoked the renderer directly in the repo where the sibling happens to be there.
    # No readlink -f: it is not portable to every /bin/sh this may run under.
    CT_SELF="$0"
    CT_HOPS=0
    while [ -L "$CT_SELF" ] && [ "$CT_HOPS" -lt 10 ]; do
        CT_LINK="$(readlink "$CT_SELF")"
        case "$CT_LINK" in
            /*) CT_SELF="$CT_LINK" ;;
            *)  CT_SELF="$(dirname "$CT_SELF")/$CT_LINK" ;;
        esac
        CT_HOPS=$((CT_HOPS + 1))
    done
    CT_BIN="$(dirname "$CT_SELF")/cost-tracker"
    if [ -x "$CT_BIN" ]; then
        if [ "$SESSION_KIND" = "local" ] || [ "$SESSION_KIND" = "free_api" ]; then
            # FREE session (local MLX or free API): there is no cloud spend to report, so the
            # cap segment is suppressed entirely and replaced by what the free work WOULD have
            # cost. DAILY_SAVED combines every free session's phantom with dispatch savings.
            JSON_OUT=$(python3 "$CT_BIN" statusline --fast --json 2>/dev/null) || JSON_OUT=
            if [ -n "$JSON_OUT" ]; then
                DAILY_SAVED=$(printf '%s' "$JSON_OUT" | python3 -c 'import sys,json
try:
    d = json.load(sys.stdin)
    t = (d.get("local_saved_usd") or 0) + (d.get("local_phantom_usd") or 0)
    if t > 0:
        print("{:.2f}".format(t))
except Exception:
    pass' 2>/dev/null) || DAILY_SAVED=
            fi
            TODAY_SEG=
        else
            TODAY_SEG=$(python3 "$CT_BIN" statusline --fast 2>/dev/null | head -1) || TODAY_SEG=
        fi
    fi
fi

[ -n "$FIVEH" ]  && LINE1="${LINE1}${SEP}${MAGENTA}5h ${FIVEH}%${RESET}"
[ -n "$SEVEND" ] && LINE1="${LINE1}${SEP}${MAGENTA}7d ${SEVEND}%${RESET}"

# --- the SPEND line ----------------------------------------------------------------
# Three session types, each with their own SPEND line format:
#   LOCAL (ports 8000-8010):      "local session saved $X · today: $Y saved with free agents"
#                                 X = this session's phantom, Y = combined daily savings
#   FREE_API (port 4141):         "free api session saved $X · today: $Y saved with free agents"
#                                 X = this session's phantom, Y = combined daily savings
#   CLOUD (default):              "session $X · today: $Z/$cap gw · local saved $W"
TODAY_LINE=
if [ "$SESSION_KIND" = "local" ] || [ "$SESSION_KIND" = "free_api" ]; then
    # FREE session. Both lanes render identically apart from the label, so they share one
    # branch: duplicating it invites the two copies drifting apart.
    #   session figure = field 4 of THIS session's ledger line (its phantom cumulative)
    #   today figure   = DAILY_SAVED, computed once above from the cost-tracker JSON
    if [ "$SESSION_KIND" = "local" ]; then FREE_LABEL="local session"; else FREE_LABEL="free api session"; fi
    SESSION_PHANTOM="0.00"
    if [ -n "$SID" ] && [ -f "$LEDGER_DIR/$SID" ]; then
        # split "<date> <cum> [<baseline>] [<local_phantom_cum>]"
        # shellcheck disable=SC2046
        set -- $(cat "$LEDGER_DIR/$SID" 2>/dev/null)
        if [ -n "${4:-}" ]; then
            SESSION_PHANTOM=$(printf '%.2f' "$4" 2>/dev/null || printf '%s' "$4")
        fi
    fi
    [ -n "$DAILY_SAVED" ] || DAILY_SAVED="0.00"
    # WEIGHT carries the emphasis here exactly as on the cloud line: the DAY is the figure that
    # matters, so it is bold while this session's contribution is dimmed beside it.
    TODAY_LINE="${DIM}${GREEN}${FREE_LABEL} ${BOLD}saved \$${SESSION_PHANTOM}${RESET}${SEP}${GREEN}today: ${BOLD}\$${DAILY_SAVED} saved${RESET}${GREEN} with free agents${RESET}"
else
    # CLOUD session. Both dollar figures live together on their own line: SESSION first, TODAY
    # second. EMPHASIS IS WEIGHT, NOT POSITION — today is the figure measured against the cap, so
    # it is BOLD while the session lifetime is DIMMED, and it reads as primary from either
    # position. Leading with it was tried and was not the lever: two figures in the same colour
    # read as equal however they are ordered, so dimming the secondary one is what separates them.
    # That decoupling lets the order follow reading habit — the session you are in, then the day it
    # sits inside — at no cost in prominence. A lone session figure is NOT dimmed: it is not
    # secondary to anything, and the "session" prefix is likewise conditional on the today segment
    # being present, since with one figure there is nothing to confuse it with.
    if [ -n "$COST_FMT" ]; then
        if [ -n "$TODAY_SEG" ]; then
            TODAY_LINE="${DIM}${YELLOW}session \$${COST_FMT}${RESET}"
        else
            TODAY_LINE="${YELLOW}\$${COST_FMT}${RESET}"
        fi
    fi
    if [ -n "$TODAY_SEG" ]; then
        TODAY_LINE="${TODAY_LINE:+$TODAY_LINE$SEP}${BOLD}${YELLOW}${TODAY_SEG}${RESET}"
    fi
fi

# Line 2 carries the VARIABLE-LENGTH names (dir / branch / worktree), which can be
# arbitrarily long per project -- keeping them off line 1 stops it from wrapping.
LINE2=
[ -n "$DIRBASE" ] && LINE2="${BOLD}${DIRBASE}${RESET}"
[ -n "$BRANCH" ] && LINE2="${LINE2:+$LINE2$SEP}${MAGENTA}${BRANCH}${RESET}"
if [ -n "$WORKTREE" ] && [ "$WORKTREE" != "$BRANCH" ] && [ "$WORKTREE" != "$DIRBASE" ]; then
  LINE2="${LINE2:+$LINE2$SEP}${DIM}${WORKTREE}${RESET}"
fi
if [ "$ADD" != "0" ] || [ "$DEL" != "0" ]; then
  LINE2="${LINE2:+$LINE2$SEP}${GREEN}+${ADD}${RESET}${DIM}/${RESET}${RED}-${DEL}${RESET}"
fi

printf '%s\n' "$LINE1"
[ -n "$TODAY_LINE" ] && printf '%s\n' "$TODAY_LINE"
[ -n "$LINE2" ] && printf '%s\n' "$LINE2"
exit 0